def solve_brute(a):
    n=len(a); best=float('-inf')
    for i in range(n):
        s=0
        for j in range(i,n):
            s+=a[j]; best=max(best,s)
    return best

def solve(a):
    # adapt: kadane / hash / two pointers / sort
    best=cur=a[0]
    for x in a[1:]:
        cur=max(x, cur+x); best=max(best,cur)
    return best
